import os.path
import re
from abc import ABC, abstractmethod

from ..command import CommandBuilder
from .exceptions import (
    CancelingAlarmError,
    ChangingMaintenanceModeError,
    JobIdNotFound,
    UnknownOperationStatus,
    UploadAlarmsError,
    UserCertificatesNotConfigured
)


class FmCliOperation(ABC):
    def __init__(self, node):
        self.ssh_node = node

    @property
    @abstractmethod
    def exception(self):
        """
        Exception that should be raised for a specific class in case of error or failure.
        """
        pass

    @abstractmethod
    def execute_fmcli_operation(self, *args, **kwargs):
        """
        Executes operation from fmCLI.sh script.
        """
        pass

    def execute(self, *args, **kwargs):
        """
        Executes operation from fmCLI.sh script and handles errors.
        """
        output = self.execute_fmcli_operation(*args, **kwargs)
        if 'unable to authorize client certificate' in output.lower():
            raise UserCertificatesNotConfigured(output)
        self.handle_errors(output)
        return output

    def handle_errors(self, output):
        """
        Handles errors if any occurred in output.
        """
        if 'error' in output.lower():
            raise self.exception(output)

    def _get_job_id(self, output):
        match = re.search(r'jobid:(?P<job_id>\d+)', output)
        try:
            return match.groupdict()['job_id']
        except (AttributeError, KeyError):
            raise JobIdNotFound(f'Job ID not found in output: {output}')

    def _wait_until_operation_completed(self, job_id):
        command = CommandBuilder(
            executable='sh fmCLI.sh',
            options={
                '-operation': 'status',
                '-jobid': job_id
            }
        )

        with self.ssh_node as ssh:
            while True:
                status = ssh.execute_command(command.text).stdout
                if 'FAILURE' in status:
                    raise self.exception('Operation failed')
                elif 'error' in status.lower():
                    raise self.exception(status)
                elif 'SUCCESS' in status:
                    return status
                elif 'RUNNING' not in status:
                    raise UnknownOperationStatus(f'Unknown operation status: "{status}"')


class CancelAlarms(FmCliOperation):

    def execute_fmcli_operation(self, dist_name, alarm_number=None, alarm_file=None, include_subnetworks=False):
        """
        Executes the bulkcancelalarms operation of the fmCLI.sh script to cancel alarms.
        http://belk.netact.noklab.net/N1X_TRUNK/topic/fm_command_line_operations/tasks/bulk_cancel_of_alarms.html

        .. note::

            The maximum supported number of parallel alarm cancel operations is 10.
            If more operations are initiated, the KW fails with a message.

        :param string dist_name: Specifies the distinguished name, e.g., ``PLMN-PLMN/MRBTS-1``.
            All alarms for specified ``dist_name`` will be canceled
            if ``alarm_number`` and ``alarm_file`` are not specified.
        :param string|int alarm_number: (Optional) Specifies the alarm number,
            ``SpecificProblem`` from output of :meth:`get_alarms` (equivalent of ``Alarm Id`` from ``WebEM``).
            Higher priority than ``alarm_file``, if both are specified then ``alarm_number`` is used.
        :param string alarm_file: (Optional) Path to file containing multiple alarm numbers:

                 - the file must be a `txt` file
                 - each line in the file must contain only one alarm number
                 - the maximum number of alarm numbers supported in the file is 1000

            Both local and remote (stored in NetAct) files are supported.
            The local one will be used if a file with the same name exists in NetAct under `/tmp/` directory.
        :param bool include_subnetworks: Specifies if child managed objects of ``dist_name`` must be considered
            while performing alarm cancel operation.
        :return: command output
        :rtype: string
        """
        include = True if alarm_number or alarm_file else None
        alarm_file = None if alarm_number else alarm_file
        if alarm_file and os.path.exists(alarm_file):
            local_file = alarm_file
            remote_file = f'/tmp/{os.path.basename(alarm_file)}'
        else:
            local_file = None
            remote_file = alarm_file

        executable = 'sh fmCLI.sh'
        options = {
            '-operation': 'bulkcancelalarms',
            '-dn': dist_name,
            '-include': include,
            '-includesubnetwork': include_subnetworks,
            '-an': alarm_number,
            '-anfile': remote_file
        }

        command = CommandBuilder(executable=executable, options=options)
        with self.ssh_node as ssh:
            try:
                if local_file:
                    ssh.put_file(local_file, remote_file)
                output = ssh.execute_command(command=command.text).stdout
            finally:
                if local_file:
                    ssh.execute_command(f'rm -f "{remote_file}"')
        return output

    def execute(self, *args, **kwargs):
        """
        Executes bulkcancelalarms operation from fmCLI.sh script and waits until it is completed.
        http://belk.netact.noklab.net/N1X_TRUNK/topic/fm_command_line_operations/tasks/bulk_cancel_of_alarms.html
        """
        output = super().execute(*args, **kwargs)
        job_id = self._get_job_id(output)
        return self._wait_until_operation_completed(job_id)

    @property
    def exception(self):
        """
        Exception that should be raised for CancelAlarms class in case of error or failure.
        """
        return CancelingAlarmError


class UploadAlarms(FmCliOperation):

    def execute_fmcli_operation(self, dist_name):
        """
        Executes the alarmupload operation of the fmCLI.sh script to cancel alarms.

        More in NA Operating Documentation at:
        Fault Management > Fault Management Operating Procedures
        > Fault Management Command Line Operations > Executing command line

        :param string dist_name: e.g. 'PLMN-PLMN/OMS-111'
        """
        command = CommandBuilder(
            executable='sh fmCLI.sh',
            options={
                '-operation': 'alarmupload',
                '-dn': dist_name
            }
        )
        with self.ssh_node as ssh:
            output = ssh.execute_command(command=command.text).stdout

        return output

    def execute(self, *args, **kwargs):
        """
        Executes alarmupload operation from fmCLI.sh script and waits until it is completed.
        """
        output = super().execute(*args, **kwargs)
        job_id = self._get_job_id(output)
        return self._wait_until_operation_completed(job_id)

    @property
    def exception(self):
        """
        Exception that should be raised for AlarmUpload class in case of error or failure.
        """
        return UploadAlarmsError


class ChangeMaintenanceMode(FmCliOperation):
    def execute_fmcli_operation(self, operation_type, dist_name, comment=None, include_subtree=False):
        """
        Executes the ``mamo`` operation of the fmCLI.sh

        More in NA Operating Documentation at:
        Fault Management > Fault Management Operating Procedures
        > Fault Management Command Line Operations > Executing command line

        :param string dist_name: e.g. 'PLMN-1/BSC-1'
        :param bool include_subtree: Specifies if subtree has to be included for maintenance mode operation
        :param string comment: Comment to be provided while setting distinguished name under maintenance mode
        :return: command output, e.g., 'Set under maintenance mode: SUCCESS'
        :rtype: string
        """
        command = CommandBuilder(
            executable='sh fmCLI.sh',
            options={'-operation': 'mamo',
                     '-operationtype': operation_type,
                     '-dn': dist_name,
                     '-includesubtree': include_subtree,
                     '-comment': comment}
        )
        with self.ssh_node as ssh:
            output = ssh.execute_command(command=command.text).stdout

        return output

    def execute(self, *args, **kwargs):
        return super().execute(*args, **kwargs)

    def handle_errors(self, output):
        if 'success' not in output.lower():
            raise self.exception(output)

    @property
    def exception(self):
        """
        Exception that should be raised for ChangeMaintenanceMode class in case of error or failure.
        """
        return ChangingMaintenanceModeError
